class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def rotateSegments(nums, ops):
    dummy = ListNode(0, build(nums))
    for l, r, k in ops:
        m = r - l + 1
        s = k % m
        if s == 0:
            continue
        before = dummy
        for _ in range(l):
            before = before.next
        seg_head = before.next
        seg_tail = seg_head
        for _ in range(m - 1):
            seg_tail = seg_tail.next
        after = seg_tail.next
        new_tail = seg_head
        for _ in range(m - s - 1):
            new_tail = new_tail.next
        new_head = new_tail.next
        seg_tail.next = seg_head
        new_tail.next = after
        before.next = new_head
    return dump(dummy.next)
